	/** 
	 * jumpstart the process by instantiating2 Coupon
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		couponId = CouponService.getCouponInstance()
		.createCoupon( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		CouponService.getCouponInstance()
				.createCoupon( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.couponSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Coupon : " + successValue.getCouponId());
							  if (successValue.getCouponId().equals(couponId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfCouponList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Coupon test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on coupon consumed")
					);
			subscriber.couponSubscribe( couponId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Coupon : " + successValue.getCouponId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfCouponList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on coupon for couponId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Coupon. 
	 */
	protected Coupon read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Coupon" );

		Coupon entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Coupon with primary key" );
		msg.append( couponId );
		
		CouponFetchOneSummary fetchOneSummary = new CouponFetchOneSummary( couponId );

		try {
			entity = CouponService.getCouponInstance().getCoupon( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Coupon " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Coupon.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Coupon." );

		StringBuilder msg = new StringBuilder( "Failed to update a Coupon : " );        
		Coupon entity = read();
		UpdateCouponCommand command = generateUpdateCommand();
		command.setCouponId(entity.getCouponId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Coupon." );

			// for use later on...
			couponId = entity.getCouponId();

			CouponService proxy = CouponService.getCouponInstance();  

			proxy.updateCoupon( command ).get();

			LOGGER.info( "-- Successfully saved Coupon - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + couponId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Coupon.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Coupon." );

		Coupon entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Coupon with id " + couponId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Coupon with id " + couponId );

			throw e;
		}

		try{
			CouponService.getCouponInstance().delete( new DeleteCouponCommand( entity.getCouponId() ) ).get();
			LOGGER.info( "-- Successfully deleted Coupon with id " + couponId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Coupon with id " + couponId );

			throw e;
		}
	}

	/**
	 * get all Coupons.
	 */
	protected List<Coupon> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Coupons:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Coupon : " );        
		List<Coupon> collection  = new ArrayList<>();

		try {
			// call the static get method on the CouponService
			collection = CouponService.getCouponInstance().getAllCoupon();
			assertNotNull( collection, "An Empty collection of Coupon was incorrectly returned.");
			
			// Now print out the values
			Coupon entity = null;            
			Iterator<Coupon> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCouponId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

